def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    best_node = None
    best_cost = float('inf')
    for candidate in unvisited_nodes:
        dist1 = distance_matrix[current_node, candidate]
        remaining = unvisited_nodes[unvisited_nodes != candidate]
        if len(remaining) > 0:
            min2 = np.min(distance_matrix[candidate, remaining])
        else:
            min2 = distance_matrix[candidate, destination_node]
        total = dist1 + min2
        if total < best_cost:
            best_cost = total
            best_node = candidate
    return best_node
